import boto3

def get_transcribe_client(region_name: str):
    return boto3.client("transcribe", region_name=region_name)

def get_translate_client(region_name: str):
    return boto3.client("translate", region_name=region_name)

def get_comprehend_client(region_name: str):
    return boto3.client("comprehend", region_name=region_name)

def get_bedrock_runtime_client(region_name: str):
    return boto3.client("bedrock-runtime", region_name=region_name)

from typing import Dict, Any, List

def normalize_transcription_job_status(response: Dict[str, Any]) -> Dict[str, Any]:
    job = response.get("TranscriptionJob", {})
    return {
        "job_id": job.get("TranscriptionJobName"),
        "status": job.get("TranscriptionJobStatus"),
        "completion_time": job.get("CompletionTime"),
        "failure_reason": job.get("FailureReason"),
        "transcript_file_uri": job.get("Transcript", {}).get("TranscriptFileUri"),
    }

def normalize_transcript_result(transcript_content: Dict[str, Any]) -> Dict[str, Any]:
    results = transcript_content.get("results", {})
    items = results.get("items", [])
    segments = results.get("speaker_labels", {}).get("segments", [])

    return {
        "full_text": results.get("transcripts", [{}])[0].get("transcript"),
        "word_timestamps": [
            {
                "word": item.get("alternatives", [{}])[0].get("content"),
                "start_time": item.get("start_time"),
                "end_time": item.get("end_time"),
                "type": item.get("type")
            } for item in items if item.get("type") == "pronunciation"
        ],
        "diarization_segments": [
            {
                "start_time": segment.get("start_time"),
                "end_time": segment.get("end_time"),
                "speaker_label": segment.get("speaker_label"),
                "items": [
                    {
                        "start_time": item.get("start_time"),
                        "end_time": item.get("end_time"),
                        "speaker_label": item.get("speaker_label"),
                        "word": item.get("alternatives", [{}])[0].get("content")
                    } for item in segment.get("items", [])
                ]
            } for segment in segments
        ]
    }

def normalize_translation_result(translation_response: Dict[str, Any]) -> str:
    return translation_response.get("TranslatedText", "")

def normalize_moderation_result(comprehend_response: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "sentiment": comprehend_response.get("Sentiment"),
        "sentiment_score": comprehend_response.get("SentimentScore"),
        "entities": comprehend_response.get("Entities", []),
        "pii_entities": comprehend_response.get("PiiEntities", []),
    }

def normalize_embedding_result(bedrock_response: Dict[str, Any]) -> List[float]:
    return bedrock_response.get("embedding", [])

import uuid

from speech_client import get_transcribe_client

def diarized_transcript(payload: dict, config: dict = None):
    config = config or {}
    client = get_transcribe_client(region_name=config.get("region"))
    job_id = config.get("job_name") or f"diarization-{uuid.uuid4().hex}"
    response = client.start_transcription_job(
        TranscriptionJobName=job_id,
        LanguageCode=payload["language_code"],
        Media={"MediaFileUri": payload["audio_uri"]},
        Settings={
            "ShowSpeakerLabels": True,
            "MaxSpeakerLabels": payload.get("max_speaker_labels", 2)
        }
    )
    return {
        "job_id": response["TranscriptionJob"]["TranscriptionJobName"],
        "status": "SUBMITTED",
    }

from typing import Dict, Any, List

from speech_models import normalize_transcript_result

def get_word_timestamps(transcript_content: Dict[str, Any]) -> List[Dict[str, Any]]:
    # Assuming transcript_content is the output from normalize_transcript_result
    return transcript_content.get("word_timestamps", [])

def get_segment_timestamps(transcript_content: Dict[str, Any]) -> List[Dict[str, Any]]:
    # Assuming transcript_content is the output from normalize_transcript_result
    # This will return segments from diarization if available, otherwise it's just words.
    # For segment timestamps without diarization, one might need to re-process words into sentences/phrases.
    # For this task, if diarization segments are present, we return those. Otherwise, we return word timestamps.
    diarization_segments = transcript_content.get("diarization_segments", [])
    if diarization_segments:
        return diarization_segments
    else:
        # If no diarization, we can consider each word as a segment for timestamping
        return transcript_content.get("word_timestamps", [])

from typing import Dict, Any

from speech_client import get_translate_client
from speech_models import normalize_translation_result

def translate_transcript(text: str, source_language_code: str, target_language_code: str, config: Dict[str, Any] = None) -> str:
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))
    response = client.translate_text(
        Text=text,
        SourceLanguageCode=source_language_code,
        TargetLanguageCode=target_language_code,
    )
    return normalize_translation_result(response)

from typing import Dict, Any

from speech_client import get_comprehend_client
from speech_models import normalize_moderation_result

def moderate_transcript(text: str, language_code: str, config: Dict[str, Any] = None) -> Dict[str, Any]:
    config = config or {}
    client = get_comprehend_client(region_name=config.get("region"))

    sentiment_response = client.detect_sentiment(Text=text, LanguageCode=language_code)
    pii_response = client.detect_pii_entities(Text=text, LanguageCode=language_code)

    # Combine results
    combined_result = {
        "Sentiment": sentiment_response["Sentiment"],
        "SentimentScore": sentiment_response["SentimentScore"],
        "PiiEntities": pii_response["Entities"],
    }

    return normalize_moderation_result(combined_result)
